        notes.Fifties <= stock.Fifties && notes.Twenties <= stock.Twenties && notes.Tens <= stock.Tens;

    /// <summary>Oracle : la combinaison exacte la plus courte parmi les billets hors cassette bloquée.</summary>
    private static NoteCounts? FewestNotes(int amount, NoteCounts stock, Denomination? jammed)
    {
        NoteCounts? best = null;
        foreach (var candidate in Stocks)
        {
            if (candidate.Value != amount || !FitsIn(candidate, stock) || Count(candidate, jammed) > 0)
            {
                continue;
            }

            if (best is { } current && candidate.Total == current.Total)
            {
                Assert.Fail($"Deux combinaisons minimales pour {amount} : {current} et {candidate}.");
            }

            if (best is not { } b || candidate.Total < b.Total)
            {
                best = candidate;
