                        {
                            Assert.Fail(
                                $"Dépôt {notes}, compte {account}, stock {stock}, bloquée {jammed?.ToString() ?? "aucune"} : " +
                                $"attendu {expected} et stock {expectedStock}, obtenu {result} et stock {dispenser.Stock}.");
                        }
                    }
                }
